"""Insertion-ordered cache (see docs/spec.md)."""


class Cache:
    def __init__(self):
        self._items = {}  # key -> [order, value]

    def put(self, key, value):
        if not isinstance(key, str) or not key:
            raise ValueError("key must be a non-empty string")
        if key in self._items:
            self._items[key][1] = value
        else:
            self._items[key] = [len(self._items), value]

    def get(self, key):
        return self._items[key][1]

    def evict_oldest(self):
        if not self._items:
            raise LookupError("empty cache")
        victim = max(self._items.items(), key=lambda kv: kv[1][0])[0]
        del self._items[victim]
        return victim

    def keys(self):
        return [k for k, _ in sorted(self._items.items(), key=lambda kv: kv[1][0])]

    def __len__(self):
        return len(self._items)
